32	const BASE_PREMIUMS: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const PROCESSING_FEE = 5;
42	
43	const WHOLE_PERCENT = 100;
44	
45	/**
46	 * Adjusts an amount by a percentage. A positive percent is a surcharge, a
47	 * negative one a discount.
48	 *
49	 * Multiplying before dividing keeps the arithmetic exact. A 1.1 multiplier
50	 * would not: floating-point `100 * 1.1` is 110.00000000000001, which rounds
51	 * up to 111 and yields a 116 G premium instead of 115 G.
52	 */
53	const adjustByPercent = (amount: number, percent: number): number =>
54	  (amount * (WHOLE_PERCENT + percent)) / WHOLE_PERCENT;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	
58	/** All rounding is in the MHPCO's favor — always up. */
59	const roundInMHPCOsFavor = Math.ceil;
60	
61	const BUILDING_BLOCK_SIZE = 3;
62	const BUILDING_BLOCK_PREMIUM = 60;
63	
64	/** Only items of one and the same kind group into a block. */
65	const areAllTheSameKind = ([first, ...rest]: InsuredItem[]): boolean =>
66	  first !== undefined && rest.every((item) => item.type === first.type);
67	
68	/**
69	 * How many flat-rate blocks this list forms. A mixed list forms none — only
70	 * alike items group — and so does any list too short to fill one block.
71	 */
72	const countCompleteBlocks = (items: InsuredItem[]): number =>
73	  areAllTheSameKind(items) ? Math.floor(items.length / BUILDING_BLOCK_SIZE) : 0;
74	
75	const CURSED_SURCHARGE_PERCENT = 50;
76	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
77	const HIGH_ENCHANTMENT_LEVEL = 5;
78	
79	/** A risk rule contributes its percent only when the item trips it. */
80	const percentWhen = (applies: boolean, percent: number): number =>
81	  applies ? percent : 0;
82	
83	const isHighlyEnchanted = (item: InsuredItem): boolean =>
84	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
85	
86	/** Risk surcharges add to the base premium; they do not compound. */
87	const riskSurchargePercentFor = (item: InsuredItem): number =>
88	  percentWhen(item.cursed === true, CURSED_SURCHARGE_PERCENT) +
89	  percentWhen(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
90	
91	/** An item's list price with its own risk surcharges applied. */
92	const riskAdjustedPremiumFor = (item: InsuredItem): number =>
93	  adjustByPercent(BASE_PREMIUMS[item.type], riskSurchargePercentFor(item));
94	
95	const sumRiskAdjustedPremiums = (items: InsuredItem[]): number =>
96	  items.reduce((sum, item) => sum + riskAdjustedPremiumFor(item), 0);
97	
98	/**
99	 * Prices an item list: alike items are grouped into building blocks sold at a
100	 * flat rate, and whatever is left over is priced item by item, each at its own
101	 * risk-adjusted premium.
102	 */
103	const priceItems = (items: InsuredItem[]): number => {
104	  const blocks = countCompleteBlocks(items);
105	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
106	
107	  return blocks * BUILDING_BLOCK_PREMIUM + sumRiskAdjustedPremiums(leftovers);
108	};
109	
110	/** A discount is a negative adjustment — long-standing customers pay 20% less. */
111	const LOYALTY_DISCOUNT_PERCENT = -20;
112	const LOYALTY_YEARS = 2;
113	
114	const isLongStanding = (customer: Customer): boolean =>
115	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
116	
117	/**
118	 * The customer's own standing modifies the item price. Unlike the risk
119	 * surcharges, which add up before being applied once, these modifiers
120	 * COMPOUND: each applies to the result of the last. A 20% discount followed
121	 * by a 10% surcharge is 100 -> 80 -> 88, not 100 -> 90.
122	 */
123	const applyCustomerModifiers = (price: number, customer: Customer): number => {
124	  const afterLoyalty = adjustByPercent(
125	    price,
126	    percentWhen(isLongStanding(customer), LOYALTY_DISCOUNT_PERCENT),
127	  );
128	
129	  return adjustByPercent(afterLoyalty, FIRST_INSURANCE_SURCHARGE_PERCENT);
130	};
131	
132	/**
133	 * The premium pipeline, in the order the spec states it: price the items,
134	 * apply the customer's modifiers, round, then add the processing fee last.
135	 */
136	const quotePremium = (
137	  items: InsuredItem[],
138	  customer: Customer,
139	): QuoteResult => ({
140	  premium:
141	    roundInMHPCOsFavor(applyCustomerModifiers(priceItems(items), customer)) +
142	    PROCESSING_FEE,
143	});
144	
145	export const runScenario = (scenario: Scenario): ScenarioResults => ({
146	  results: scenario.steps.map((step) =>
147	    quotePremium(step.items ?? [], scenario.customer),
148	  ),
149	});
